  // Claves con {s} (cualquier texto) o {n} (número) → patrones
  var PATTERNS = [];
  var esc = function (s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); };
  Object.keys(D).forEach(function (k) {
    if (k.indexOf('{s}') < 0 && k.indexOf('{n}') < 0) return;
    var src = esc(k).replace(/\\\{s\\\}/g, '(.+?)').replace(/\\\{n\\\}/g, '(\\d[\\d.,]*)');
    PATTERNS.push([new RegExp('^' + src + '$'), D[k]]);
  });
  // Números automáticos: "0 caracteres" → "0 characters" sirve también para "12 caracteres"
  var NUMD = {};
  Object.keys(D).forEach(function (k) {
    var nk = k.match(/\d+/g), nv = D[k].match(/\d+/g);
    if (!nk || !nv || nk.join() !== nv.join()) return;
    var i = 0, j = 0;
    NUMD[k.replace(/\d+/g, '{#}')] = D[k].replace(/\d+/g, '{#}');
  });

  function norm(s) { return s.replace(/\s+/g, ' ').trim(); }
  function fill(tpl, vals) { var i = 0; return tpl.replace(/\{[sn#]\}/g, function () { return vals[i++] !== undefined ? vals[i - 1] : ''; }); }
  function lookup(k) {
    if (Object.prototype.hasOwnProperty.call(D, k)) return D[k];
    for (var i = 0; i < PATTERNS.length; i++) {
      var m = k.match(PATTERNS[i][0]);
      if (m) return fill(PATTERNS[i][1], m.slice(1).map(function (x) { return tr(x) || x; }));
    }
    var nums = k.match(/\d+/g);
    if (nums) { var t = NUMD[k.replace(/\d+/g, '{#}')]; if (t) return fill(t, nums); }
    return null;
  }
  // Prueba el texto entero y, si no, sin los emojis/símbolos del principio y la puntuación del final
  function tr(s) {
    var k = norm(s); if (!k || !/[A-Za-zÁÉÍÓÚÑáéíóúñ]/.test(k)) return null;
    var r = lookup(k); if (r !== null) return r;
    var m = k.match(/^([^A-Za-zÁÉÍÓÚÑáéíóúñ0-9¿¡"«({!@#]*)(.*?)([\s:.…!?)»"]*)$/);
    if (m && (m[1] || m[3]) && m[2]) {
      r = lookup(m[2] + m[3]); if (r !== null) return m[1] + r;
      r = lookup(m[2]); if (r !== null) return m[1] + r + m[3];
    }
    return null;
  }
  window.silklyT = function (s) { return tr(String(s)) || s; };

